WITH canonical_sources(name,body_hex) AS (VALUES ('enqueue_livenet_readiness_epoch',''),('enqueue_livenet_readiness_epoch_for_meta',''),('commit_livenet_readiness_epoch','')), selected_functions AS (
 SELECT p.*,n.nspname,l.lanname,pg_get_userbyid(p.proowner) AS owner_name
 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace JOIN pg_catalog.pg_language l ON l.oid=p.prolang
 WHERE n.nspname='proof_indexer' AND p.proname IN ('enqueue_livenet_readiness_epoch','enqueue_livenet_readiness_epoch_for_meta','commit_livenet_readiness_epoch')
), functions AS (
 SELECT proname AS name,owner_name AS owner,lanname AS language,prosecdef AS "securityDefiner",proconfig AS config,prokind::text AS kind,pronargs::integer AS "argumentCount",proretset AS "returnsSet",prorettype::integer AS "returnTypeOid",provolatile::text AS volatility,proparallel::text AS parallel,proisstrict AS strict,proleakproof AS "leakProof",prosupport::integer AS "supportOid",
 (prosrc=convert_from(decode((SELECT body_hex FROM canonical_sources WHERE name=proname),'hex'),'UTF8')) AS "canonicalSourceEquality",
 encode(sha256(convert_to(prosrc,'UTF8')),'hex') AS "sourceSha256",octet_length(prosrc) AS "sourceBytes",
 encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex') AS "definitionSha256",
 COALESCE((SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) FROM aclexplode(COALESCE(proacl,acldefault('f',proowner))) a),'[]'::jsonb) AS acl
 FROM selected_functions
), selected_relations AS (
 SELECT c.*,pg_get_userbyid(c.relowner) AS owner_name FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='proof_indexer' AND c.relname IN ('mail_items','meta','readiness_epoch_queue','readiness_epoch_shards')
), relations AS (
 SELECT c.relname AS name,c.owner_name AS owner,c.relkind::text AS kind,c.relpersistence::text AS persistence,c.relrowsecurity AS rls,c.relforcerowsecurity AS "forceRls",(SELECT amname FROM pg_am WHERE oid=c.relam) AS "accessMethod",
 (SELECT count(*) FROM pg_rewrite WHERE ev_class=c.oid) AS "ruleCount",(SELECT count(*) FROM pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid) AS "inheritanceCount",
 COALESCE((SELECT jsonb_agg(jsonb_build_object('ordinal',a.attnum,'name',a.attname,'typeOid',a.atttypid::integer,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'dropped',a.attisdropped,'identity',a.attidentity::text,'generated',a.attgenerated::text,'defaultSha256',CASE WHEN d.adbin IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(d.adbin,d.adrelid),'UTF8')),'hex') END,'acl',COALESCE((SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable) FROM aclexplode(a.attacl) x),'[]'::jsonb)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0),'[]'::jsonb) AS columns,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('name',co.conname,'type',co.contype::text,'validated',co.convalidated,'deferrable',co.condeferrable,'initiallyDeferred',co.condeferred,'definitionSha256',encode(sha256(convert_to(pg_get_constraintdef(co.oid),'UTF8')),'hex')) ORDER BY co.conname) FROM pg_constraint co WHERE co.conrelid=c.oid),'[]'::jsonb) AS constraints,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'unique',i.indisunique,'primary',i.indisprimary,'immediate',i.indimmediate,'exclusion',i.indisexclusion,'nullsNotDistinct',i.indnullsnotdistinct,'definitionSha256',encode(sha256(convert_to(pg_get_indexdef(i.indexrelid),'UTF8')),'hex')) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),'[]'::jsonb) AS indexes,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) FROM aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a),'[]'::jsonb) AS acl
 FROM selected_relations c
), triggers AS (
 SELECT c.relname AS relation,t.tgname AS name,p.proname AS function,pn.nspname AS "functionSchema",t.tgenabled::text AS enabled,t.tgtype::integer AS type,t.tgisinternal AS internal,t.tgdeferrable AS deferrable,t.tginitdeferred AS "initiallyDeferred",(t.tgconstraint<>0) AS "hasConstraint",t.tgnargs::integer AS "argumentCount",octet_length(t.tgargs) AS "argumentBytes",(t.tgqual IS NULL) AS "noCondition",t.tgoldtable AS "oldTransitionTable",t.tgnewtable AS "newTransitionTable",(t.tgparentid=0) AS "noParent",encode(sha256(convert_to(pg_get_triggerdef(t.oid,true),'UTF8')),'hex') AS "definitionSha256"
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace
 WHERE n.nspname='proof_indexer' AND (t.tgname LIKE 'readiness_epoch_%' OR c.relname IN ('mail_items','meta','readiness_epoch_queue','readiness_epoch_shards'))
), owner_role AS (
 SELECT rolname AS name,rolcanlogin AS login,rolsuper AS superuser,rolcreaterole AS "createRole",rolcreatedb AS "createDb",rolreplication AS replication,rolbypassrls AS "bypassRls",rolinherit AS inherit,rolconnlimit AS "connectionLimit",(rolvaliduntil IS NULL) AS "noExpiry",(rolconfig IS NULL) AS "noConfiguration",has_schema_privilege(oid,'proof_indexer','USAGE') AS "schemaUsage",(SELECT count(*) FROM pg_auth_members WHERE roleid=r.oid OR member=r.oid) AS memberships FROM pg_roles r WHERE rolname='proof_indexer_readiness_owner'
), closure AS (
 SELECT jsonb_build_object('schema','pow-audit30-readiness-public-closure-v1','functions',COALESCE((SELECT jsonb_agg(to_jsonb(f) ORDER BY name) FROM functions f),'[]'::jsonb),'relations',COALESCE((SELECT jsonb_agg(to_jsonb(r) ORDER BY name) FROM relations r),'[]'::jsonb),'triggers',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY relation,name) FROM triggers t),'[]'::jsonb),'ownerRole',COALESCE((SELECT to_jsonb(o) FROM owner_role o),'null'::jsonb)) AS value
)
SELECT jsonb_build_object('closure',value,'closureSha256',encode(sha256(convert_to(value::text,'UTF8')),'hex'),'snapshot',pg_current_snapshot()::text,'identity',jsonb_build_object('database',current_database(),'user',current_user,'serverVersion',current_setting('server_version_num'),'transactionReadOnly',current_setting('transaction_read_only'),'searchPath',current_setting('search_path'),'maxPreparedTransactions',current_setting('max_prepared_transactions')),'dataSummary',jsonb_build_object('queueRows',(SELECT count(*) FROM proof_indexer.readiness_epoch_queue),'shardRows',(SELECT count(*) FROM proof_indexer.readiness_epoch_shards),'livenetShardRows',(SELECT count(*) FROM proof_indexer.readiness_epoch_shards WHERE network='livenet'),'validLivenetShards',(SELECT count(*) FROM proof_indexer.readiness_epoch_shards WHERE network='livenet' AND shard BETWEEN 0 AND 63 AND epoch>=1))) AS value FROM closure;
